"""Write report/tables.md: the reflection tables the report quotes.

Generated, never edited by hand, so a number in the report can always be traced to the
model that produced it.
"""

from __future__ import annotations

import pathlib

from xrdsim.diffractometer import Instrument, reflections
from xrdsim.samples import PHASES

HERE = pathlib.Path(__file__).resolve().parent
OUT = HERE / "tables.md"


def build() -> None:
    instrument = Instrument()
    lines = [
        "# Reflection tables",
        "",
        "Generated by `uv run python -m report.tables`. Cu K-alpha1 = "
        f"{instrument.wavelength:.6f} A, K-alpha2 included in the scan but not in the "
        "intensity column, which is relative to the strongest reflection of each phase.",
        "",
    ]
    for key, phase in PHASES.items():
        rows = [row for row in reflections(phase, instrument) if row.intensity > 1e-9]
        if not rows:
            continue
        strongest = max(row.intensity for row in rows)
        lines += [
            f"## {phase.name} ({phase.formula}), {phase.space_group}",
            "",
            f"Cell: a = {phase.a:.4f}" + (f", c = {phase.c:.4f}" if phase.c else "")
            + f" A. Source: {phase.source}",
            "",
            "| hkl | d (A) | 2theta (deg) | m | I/I0 (%) |",
            "| --- | --- | --- | --- | --- |",
        ]
        for row in rows:
            label = "".join(str(v) for v in row.hkl)
            lines.append(f"| {label} | {row.d:.4f} | {row.two_theta:.3f} | "
                         f"{row.multiplicity} | {100.0 * row.intensity / strongest:.1f} |")
        lines.append("")
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUT} ({len(lines)} lines)")


if __name__ == "__main__":
    build()
